import torch.nn as nn
import torch

class TwoTower(nn.Module):
    def __init__(self):
        super().__init__()
        self.user_tower = nn.Sequential(nn.Linear(50, 128), nn.ReLU(), nn.Linear(128, 64))
        self.item_tower = nn.Sequential(nn.Linear(100, 128), nn.ReLU(), nn.Linear(128, 64))
    def forward(self, user_feats, item_feats):
        u = self.user_tower(user_feats)
        i = self.item_tower(item_feats)
        return torch.sum(u * i, dim=-1)
